        "CREATE TABLE mode_rows ("
        "id INT PRIMARY KEY, tag INT, "
        "CONSTRAINT mode_rows_tag_key UNIQUE (tag) "
        "DEFERRABLE INITIALLY IMMEDIATE)",
        session));
    assert(g_engine.insert(db, "mode_rows", {{"id", "1"}, {"tag", "10"}}) ==
           dbms::DBStatus::OK);

